window.AUTH=window.AUTH||{};window.AUTH["20-437"]={"d":"20-437","id":"2020/20-437","n":"United States v. Palomar-Santiago","briefs":[{"k":"petitioner","label":"Brief of petitioner United States","date":"2021-02-22","url":"https://www.supremecourt.gov/DocketPDF/20/20-437/169643/20210222192625892_20-437tsUnitedStates.pdf","side":"pet","n":85},{"k":"respondent","label":"Brief of respondent Refugio Palomar-Santiago","date":"2021-03-24","url":"https://www.supremecourt.gov/DocketPDF/20/20-437/172876/20210324154838708_Palomar-Santiago_Response_Brief.pdf","side":"res","n":98},{"k":"reply","label":"Reply of petitioner United States","date":"2021-04-16","url":"https://www.supremecourt.gov/DocketPDF/20/20-437/175908/20210416105240876_20-437rbUnitedStates.pdf","side":"pet","n":63}],"opinion":"https://www.supremecourt.gov/opinions/20pdf/593us2r38_n648.pdf","tr":true,"items":[{"t":"case","label":"Booth v. Churner","cite":"532 U.S. 731","y":2001,"id":"2000/99-1964","sc":1,"sum":"The Court held that even though the prison grievance procedure did not provide for requested monetary relief, Booth was nonetheless required to exhaust administrative remedies before filing suit with respect to prison conditions.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"Bousley v. United States","cite":"523 U.S. 614","y":1998,"id":"1997/96-8516","sc":1,"sum":"The Court held that, although Bousley's claim was procedurally defaulted, Bousley may be entitled to a hearing on the merits of it if he makes the necessary showing to relieve the default.","sumSrc":"Oyez","by":{"0":"24, 25, 34","1":"passim","2":"6"}},{"t":"case","label":"Brady v. United States","cite":"397 U.S. 742","y":1970,"id":"1969/270","sc":1,"sum":"The Supreme Court held that United States v. Jackson does not require every guilty plea to be overturned when fear of death was a factor in the plea. The voluntariness of the plea is determined by considering all of the relevant circumstances. While Brady may have been partially motivated by a desire to avoid the death penalty, the guilty plea was voluntarily made with the advice of competent counsel.","sumSrc":"Oyez","by":{"0":"20, 21","1":"39","2":"6"}},{"t":"case","label":"Coit Independence Joint Venture v. Federal Sav. & Loan Ins. Corp.","cite":"489 U.S. 561","y":1989,"id":"1988/87-996","sc":1,"sum":"Due to disagreements about loans to petitioner by FirstSouth, F. A., a federal savings and loan association, petitioner filed suit against FirstSouth in state court, alleging various state law causes of action and seeking damages and equitable relief. Two months later, the Federal Home Loan Bank Board (Bank Board) determined that FirstSouth was insolvent and appointed as receiver the Federal Savings and Loan …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16"}},{"t":"case","label":"Custis v. United States","cite":"511 U.S. 485","y":1994,"id":"1993/93-5209","sc":1,"sum":"After the jury convicted petitioner Custis of possession of a firearm by a felon and another federal crime, the Government relied on his prior state-court convictions for robbery in Pennsylvania and for burglary and attempted burglary in Maryland to support a motion under the Armed Career Criminal Act of 1984, 18 U. S. C. § 924(e) (ACCA), which provides for enhancement of the sentence of a convicted firearms …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34","1":"23"}},{"t":"case","label":"Daniels v. United States","cite":"532 U.S. 374","y":2001,"id":"2000/99-9136","sc":1,"sum":"The Court held that the nonexistent or unsuccessful pursuit of available challenges to the constitutionality of prior state convictions, which were used to enhance a federal sentence, precluded such challenge to collaterally attack a federal sentence. \"[Daniels] could have pursued his claims while he was in custody on those convictions,\" wrote Justice O'Connor for the majority. \"As his counsel conceded at oral argument, there is no indication that [Daniels] did so or that he was prevented from doing so by some external force.\".","sumSrc":"Oyez","by":{"0":"34","1":"23","2":"17"}},{"t":"case","label":"Kawashima v. Holder","cite":"565 U.S. 478","y":2012,"id":"2011/10-577","sc":1,"sum":"The Court held that filing a false tax return in violation of 26 U.S.C. Section 7206 qualifies as an aggravated felony under the Immigration and Nationality Act if the Government's revenue loss exceeds $10,000.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"(III) Cases—Continued: Leocal v. Ashcroft","cite":"543 U.S. 1","y":2004,"id":"2004/03-583","sc":1,"op":1,"sum":"The Court held that state DUI offenses, except when involving purposeful intent, are accidental and not crimes of violence under federal law. Le therefore did not commit an aggravated felony for which he could be deported.","sumSrc":"Oyez","by":{"0":"4, 8, 17, 26","1":"1, 6, 21, 38"}},{"t":"case","label":"Lewis v. United States","cite":"445 U.S. 55","y":1980,"id":"1979/78-1595","sc":1,"sum":"Even though petitioner's extant prior state-court felony conviction may be subject to collateral attack under Gideon v. Wainwright, 372 U. S. 335, it could properly be used as a predicate for his subsequent conviction for possession of a firearm in violation of § 1202 (a) (1) of Title VII of the Omnibus Crime Control and Safe Streets Act of 1968.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34","1":"22, 33","2":"13, 15, 16, 17, 18"}},{"t":"case","label":"Martinez-Sanchez v. INS","cite":"22 Fed. Appx. 755","y":2001,"court":"9th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./22/755/","sum":"Holding that the California offense of DUI causing bodily injury to another person is not an aggravated felony.","sumSrc":"brief:0","by":{"0":"26"}},{"t":"case","label":"McCarthy v. Madigan","cite":"503 U.S. 140","y":1992,"id":"1991/90-6861","sc":1,"sum":"Exhaustion of the Bureau of Prisons' administrative procedure is not required before a federal prisoner can initiate a Bivens action solely for money damages.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16, 35"}},{"t":"case","label":"McKart v. United States","cite":"395 U.S. 185","y":1969,"id":"1968/403","sc":1,"sum":"Petitioner had been classified IV-A (sole surviving son status). When the Selective Service Board learned of the death of petitioner's mother, it reclassified him I-A (available for military service), on the theory that the IV-A classification became improper when the \"family unit\" ceased to exist. Petitioner did not appeal the reclassification. Upon his failure to report as ordered for his pre-induction physical …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34, 35","1":"35, 44, 45","2":"4"}},{"t":"case","label":"McNeil v. United States","cite":"508 U.S. 106","y":1993,"id":"1992/92-6033","sc":1,"sum":"An FTCA action may not be maintained when the claimant failed to exhaust his administrative remedies prior to filing suit, but did so before substantial progress was made in the litigation. Section 2675(a)'s unambiguous text-which commands that an \"action shall not be instituted...unless the claimant shall have first presented the claim to the appropriate... agency and his claim shall have been finally denied by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16"}},{"t":"case","label":"Mellouli v. Lynch","cite":"575 U.S. 798","y":2015,"id":"2014/13-1034","sc":1,"sum":"The Government must prove the connection between a state drug paraphernalia conviction and a substance listed in the Controlled Substances Act to trigger deportability under the Immigration and Nationality Act.","sumSrc":"Oyez","by":{"0":"17, 26"}},{"t":"case","label":"Merit Mgmt. Grp., LP v. FTI Consulting, Inc.","cite":"138 S. Ct. 883","y":2018,"id":"2017/16-784","sc":1,"sum":"The Court held that the safe harbor provision of 11 U.S.C. § 546(e), which prohibits a trustee from avoiding a transfer made by or to a financial institution, does not include transfers where the benefit and detriment of the transfer impact companies that are not financial institutions.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Moncrieffe v. Holder","cite":"569 U.S. 184","y":2013,"id":"2012/11-702","sc":1,"sum":"The Court found that distribution of small amounts of marijuana does not constitute an aggravated felony and thus, does not require deportation of the distributor.","sumSrc":"Oyez","by":{"0":"17","1":"41"}},{"t":"case","label":"Nasrallah v. Barr","cite":"140 S. Ct. 1683","y":2020,"id":"2019/18-1432","sc":1,"sum":"The Court held that the federal courts have jurisdiction to review an administrative agency’s factual findings underlying denials of withholding (and deferral) of removal relief, notwithstanding 8 U.S.C. § 1252(a)(2)(C), which seems to divest courts of jurisdiction in such cases.","sumSrc":"Oyez","by":{"0":"4"}},{"t":"case","label":"Nijhawan v. Holder","cite":"557 U.S. 29","y":2009,"id":"2008/08-495","sc":1,"sum":"The Court found that when an alien is convicted of conspiracy and held responsible for causing more than $10,000 in damages, the statute requirement used by the Immigration and Nationality Act (INA) to deport the alien is satisfied, even if the $10,000 is not established by a jury.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Rotkiske v. Klemm","cite":"140 S. Ct. 355","y":2019,"id":"2019/18-328","sc":1,"sum":"The Court held that the one-year statute of limitations under the Fair Debt Collection Practices Act begins when the violation occurred, not when the violation was discovered.","sumSrc":"Oyez","by":{"0":"14"}},{"t":"case","label":"Ross v. Blake","cite":"136 S. Ct. 1850","y":2016,"id":"2015/15-339","sc":1,"op":2,"sum":"The Court determined that the Prison Litigation Reform Act’s requirement to exhaust administrative remedies does not have a “special circumstances” exception.","sumSrc":"Oyez","by":{"0":"16, 22, 23, 24, 25, 26","1":"passim","2":"3, 4, 6"}},{"t":"case","label":"Sanchez-Llamas v. Oregon","cite":"548 U.S. 331","y":2006,"id":"2005/04-10566","sc":1,"sum":"The Court affirmed the Oregon Supreme Court and ruled that evidence obtained in violation of Article 36 of the Vienna Convention need not be excluded from trial.","sumSrc":"Oyez","by":{"0":"24","1":"40"}},{"t":"case","label":"Sessions v. Dimaya","cite":"138 S. Ct. 1204","y":2018,"id":"2017/15-1498","sc":1,"sum":"A case in which the Court struck down the Immigration and Nationality Act’s “crime of violence” provision as unconstitutionally vague in violation of the Due Process Clause of the Fifth Amendment.","sumSrc":"Oyez","by":{"0":"3"}},{"t":"case","label":"Torres v. Lynch","cite":"136 S. Ct. 1619","y":2016,"url":"https://www.courtlistener.com/c/S.%20Ct./136/1619/","sc":1,"by":{"0":"3, 20"}},{"t":"case","label":"United States v. Adame-Orozco","cite":"607 F.3d 647","y":2006,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/607/647/","sum":"Explaining that the first “element” of Section 1326(a) is a prior removal order, which “enjoys a presumption of regularity” that the defendant may rebut by “prov[ing] each of § 1326(d)’s elements”.","sumSrc":"brief:2","by":{"0":"29","1":"34","2":"9"}},{"t":"case","label":"United States v. Aguilera-Rios","cite":"769 F.3d 626","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/769/626/","by":{"0":"6, 27","1":"7, 12, 21, 50","2":"8"}},{"t":"case","label":"United States v. Arrieta","cite":"224 F.3d 1076","y":2000,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/224/1076/","by":{"0":"18, 20"}},{"t":"case","label":"United States v. Camacho-Lopez","cite":"450 F.3d 928","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/450/928/","by":{"0":"18, 27","1":"11"}},{"t":"case","label":"United States v. Cervantes-Gonzales","cite":"238 Fed. Appx. 278","y":2007,"court":"9th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./238/278/","by":{"0":"27"}},{"t":"case","label":"United States v. Delacruz-Soto","cite":"414 F.3d 1158","y":2005,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/414/1158/","by":{"0":"30"}},{"t":"case","label":"United States v. Estrada","cite":"876 F.3d 885","y":2017,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/876/885/","by":{"0":"15"}},{"t":"case","label":"United States v. Frady","cite":"456 U.S. 152","y":1982,"id":"1981/80-1595","sc":1,"sum":"In 1963, respondent was convicted of first-degree murder and sentenced to death by a jury in the Federal District Court for the District of Columbia, which at that time had exclusive jurisdiction over local felonies committed in the District. The Court of Appeals for the District of Columbia Circuit, which then acted as the local appellate court, upheld the conviction but set aside the death sentence, and respondent …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34","1":"39, 40"}},{"t":"case","label":"United States v. Gonzalez-Villalobos","cite":"724 F.3d 1125","y":2013,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/724/1125/","sum":"Holding that a defendant cannot satisfy Section 1326(d)(2) where he “did, in fact, seek judicial review” by filing and then dismissing a petition for a writ of habeas corpus.","sumSrc":"brief:0","by":{"0":"37"}},{"t":"case","label":"United States v. Hernandez-Perdomo","cite":"948 F.3d 807","y":2020,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/948/807/","sum":"Noting that the “language” of what would become Section 1326(d) was “taken directly from the U.S. Supreme Court case of United States v. Mendoza-Lopez”.","sumSrc":"brief:0","by":{"0":"5, 6, 27, 28, 30"}},{"t":"case","label":"United States v. Jackson","cite":"390 U.S. 570","y":1968,"id":"1967/85","sc":1,"sum":"The death penalty clause imposes an impermissible burden upon the exercise of a constitutional right, but that provision is severable from the remainder of the Act and the unconstitutionality of that clause does not require the defeat of the Act as a whole. Pp. 572-591. 262 F. Supp. 716, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"United States v. Lopez","cite":"445 F.3d 90","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/445/90/","op":3,"ar":8,"sum":"Observing that because “the government [in MendozaLopez] did not challenge” the district court’s findings, “th[is] Court assumed that the[] failures by the [immigration judge] violated the aliens’ due process rights and concluded that the violation amounted to a complete denial of judicial review”.","sumSrc":"brief:0","by":{"0":"32"}},{"t":"case","label":"United States v. Martinez-Hernandez","cite":"932 F.3d 1198","y":2019,"url":"https://www.courtlistener.com/c/F.3d/932/1198/","by":{"0":"6"}},{"t":"case","label":"United States v. Mendoza-Lopez","cite":"481 U.S. 828","y":1987,"id":"1986/85-2067","sc":1,"op":2,"ar":8,"sum":"Title 8 U. S. C. § 1326 provides that any alien who has been deported and thereafter enters the United States is guilty of a felony. Respondents, Mexican nationals, were arrested and deported after a group hearing at which they purportedly waived their rights to apply for suspension of deportation and to appeal. Subsequently, respondents were again arrested in this country and indicted on charges of violating § …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"passim","2":"passim"}},{"t":"case","label":"United States v. Morales","cite":"634 Fed. Appx. 606","y":2016,"court":"9th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./634/606/","by":{"0":"27"}},{"t":"case","label":"United States v. Muro-Inclan","cite":"249 F.3d 1180","y":2001,"url":"https://www.courtlistener.com/c/F.3d/249/1180/","by":{"0":"18, 20, 36"}},{"t":"case","label":"United States v. Nguyen","cite":"235 F.3d 1179","y":2000,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/235/1179/","by":{"0":"21","1":"40"}},{"t":"case","label":"United States v. Ochoa","cite":"861 F.3d 1010","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/861/1010/","op":1,"sum":"Describing the evolution of Ninth Circuit law.","sumSrc":"brief:0","by":{"0":"passim","1":"7, 12","2":"8, 12"}},{"t":"case","label":"United States v. Pallares-Galan","cite":"359 F.3d 1088","y":2004,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/359/1088/","by":{"0":"18, 19, 27","1":"11"}},{"t":"case","label":"United States v. Rodriguez","cite":"420 F.3d 831","y":2005,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/420/831/","op":1,"by":{"0":"20"}},{"t":"case","label":"United States v. Santiago-Ochoa","cite":"447 F.3d 1015","y":2006,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/447/1015/","by":{"0":"19"}},{"t":"case","label":"United States v. Soto-Mateo","cite":"799 F.3d 117","y":2015,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/799/117/","op":1,"by":{"0":"15, 20"}},{"t":"case","label":"United States v. Trinidad-Aquino","cite":"259 F.3d 1140","y":2001,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/259/1140/","sum":"Interpreting 18 U.S.C. 16(b) for purposes of Sentencing Guidelines § 2L1.2(b)(1)(A) (1998).","sumSrc":"brief:0","by":{"0":"8"}},{"t":"case","label":"United States v. Ubaldo-Figueroa","cite":"364 F.3d 1042","y":2004,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/364/1042/","by":{"0":"6"}},{"t":"case","label":"United States v. United Mine Workers of America","cite":"330 U.S. 258","y":1947,"id":"scdb/1946-060","sc":1,"sum":"1. Neither the Norris-LaGuardia Act, 47 Stat. 70, nor § 20 of the Clayton Act, 38 Stat. 738, deprives a federal district court of jurisdiction to issue a restraining order and preliminary injunction in a suit by the Government to prevent a union and its officers from precipitating a nation-wide strike in the bituminous coal mines pending judicial interpretation of a labor contract between the Government and the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34"}},{"t":"case","label":"United States v. Villarreal Silva","cite":"931 F.3d 330","y":2019,"url":"https://www.courtlistener.com/c/F.3d/931/330/","by":{"0":"6"}},{"t":"case","label":"Valencia-Valencia v. INS","cite":"22 Fed. Appx. 754","y":2001,"court":"9th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./22/754/","by":{"0":"8, 26"}},{"t":"case","label":"Yakus v. United States","cite":"321 U.S. 414","y":1944,"id":"1940-1955/321us414","sc":1,"ar":6,"sum":"The Supreme Court held that Congress sufficiently regulated the powers of the Administrator of the Act in such a way as to be a constitutional delegation of legislative power to obtain a particular objective. The Constitution grants Congress the necessary flexibility to perform its legislative function in a variety of ways.","sumSrc":"Oyez","by":{"0":"34, 35","1":"18, 19","2":"2, 16, 20"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"0":"21"}},{"t":"law","label":"Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"0":"5, 30"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(43)","(a)(43)(F)","(a)(47)"],"stext":{"head":"§1101. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"administrator\" means the official designated by the Secretary of State pursuant to section 1104(b) of this title."],[0,"(2) The term \"advocates\" includes, but is not limited to, advises, recommends, furthers by overt act, and admits belief in."],[0,"(3) The term \"alien\" means any person not a citizen or national of the United States."],[0,"(4) The term \"application for admission\" has reference to the application for admission into the United States and not to the application for the issuance of an immigrant or nonimmigrant visa."],[0,"(5) The term \"Attorney General\" means the Attorney General of the United States."],[0,"(6) The term \"border crossing identification card\" means a document of identity bearing that designation issued to an alien who is lawfully admitted for permanent residence, or to an alien who is a resident in foreign contiguous territory, by a consular officer or an immigration officer for the purpose of crossing over the borders between the United States and foreign contiguous territory in accordance with such conditions for its issuance and use as may be prescribed by regulations. Such regulations shall provide that (A) each such document include a biometric identifier (such as the fingerprint or handprint of the alien) that is machine readable and (B) an alien presenting a border crossing identification card is not permitted to cross over the border into the United States unless the biometric identifier contained on the card matches the appropriate biometric characteristic of the alien."],[0,"(7) The term \"clerk of court\" means a clerk of a naturalization court."],[0,"(8) The terms \"Commissioner\" and \"Deputy Commissioner\" mean the Commissioner of Immigration and Naturalization and a Deputy Commissioner of Immigration and Naturalization, respectively."],[0,"(9) The term \"consular officer\" means any consular, diplomatic, or other officer or employee of the United States designated under regulations prescribed under authority contained in this chapter, for the purpose of issuing immigrant or nonimmigrant visas or, when used in subchapter III, for the purpose of adjudicating nationality."],[0,"(10) The term \"crewman\" means a person serving in any capacity on board a vessel or aircraft."],[0,"(11) The term \"diplomatic visa\" means a nonimmigrant visa bearing that title and issued to a nonimmigrant in accordance with such regulations as the Secretary of State may prescribe."],[0,"(12) The term \"doctrine\" includes, but is not limited to, policies, practices, purposes, aims, or procedures."],[0,"(13)(A) The terms \"admission\" and \"admitted\" mean, with respect to an alien, the lawful entry of the alien into the United States after inspection and authorization by an immigration officer."],[0,"(B) An alien who is paroled under section 1182(d)(5) of this title or permitted to land temporarily as an alien crewman shall not be considered to have been admitted."],[0,"(C) An alien lawfully admitted for permanent residence in the United States shall not be regarded as seeking an admission into the United States for purposes of the immigration laws unless the alien—"],[1,"(i) has abandoned or relinquished that status,"],[1,"(ii) has been absent from the United States for a continuous period in excess of 180 days,"],[1,"(iii) has engaged in illegal activity after having departed the United States,"],[1,"(iv) has departed from the United States while under legal process seeking removal of the alien from the United States, including removal proceedings under this chapter and extradition proceedings,"],[1,"(v) has committed an offense identified in section 1182(a)(2) of this title, unless since such offense the alien has been granted relief under section 1182(h) or 1229b(a) of this title, or"],[1,"(vi) is attempting to enter at a time or place other than as designated by immigration officers or has not been admitted to the United States after inspection and authorization by an immigration officer."],[0,"(14) The term \"foreign state\" includes outlying possessions of a foreign state, but self-governing dominions or territories under mandate or trusteeship shall be regarded as separate foreign states."],[0,"(15) The term \"immigrant\" means every alien except an alien who is within one of the following classes of nonimmigrant aliens—"],[1,"(A)(i) an ambassador, public minister, or career diplomatic or consular officer who has been accredited by a foreign government, recognized de jure by the United States and who is accepted by the President or by the Secretary of State, and the members of the alien's immediate family;"],[1,"(ii) upon a basis of reciprocity, other officials and employees who have been accredited by a foreign government recognized de jure by the United States, who are accepted by the Secretary of State, and the members of their immediate families; and"],[1,"(iii) upon a basis of reciprocity, attendants, servants, personal employees, and members of their immediate families, of the officials and employees who have a nonimmigrant status under (i) and (ii) above;"],[1,"(B) an alien (other than one coming for the purpose of study or of performing skilled or unskilled labor or as a representative of foreign press, radio, film, or other foreign information media coming to engage in such vocation) having a residence in a foreign country which he has no intention of abandoning and who is visiting the United States temporarily for business or temporarily for pleasure;"],[1,"(C)(i) an alien in immediate and continuous transit through the United States, for a period not to exceed 29 days;"],[1,"(ii) an alien who qualifies as a person entitled to pass in transit to and from the United Nations Headquarters District (as defined in section 4309a(e) of title 22) and foreign countries, under the provisions of paragraphs (3), (4), and (5) of section 11 of the Agreement regarding the Headquarters of the United Nations, done at Lake Success June 26, 1947 (61 Stat. 758); or"],[1,"(iii) an alien passing in transit through the United States to board a vessel on which the alien will perform, or to disembark from a vessel on which the alien performed, ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, for a period not to exceed 180 days;"],[1,"(D)(i) an alien crewman serving in good faith as such in a capacity required for normal operation and service on board a vessel, as defined in section 1288(a) of this title (other than a fishing vessel having its home port or an operating base in the United States), or aircraft, who intends to land temporarily and solely in pursuit of his calling as a crewman and to depart from the United States with the vessel or aircraft on which he arrived or some other vessel or aircraft;"],[1,"(ii) an alien crewman serving in good faith as such in any capacity required for normal operations and service aboard a fishing vessel having its home port or an operating base in the United States who intends to land temporarily in Guam or the Commonwealth of the Northern Mariana Islands and solely in pursuit of his calling as a crewman and to depart from Guam or the Commonwealth of the Northern Mariana Islands with the vessel on which he arrived; or"],[1,"(iii) an alien crewman performing ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, who intends to land temporarily solely in pursuit of the alien's responsibilities as a crewman and to depart from the United States on the vessel on which the alien arrived or on another vessel or aircraft, for a period not to exceed 180 days;"],[1,"(E) an alien entitled to enter the United States under and in pursuance of the provisions of a treaty of commerce and navigation between the United States and the foreign state of which the alien is a national (or, in the case of an alien who acquired the relevant nationality through a financial investment and who has not previously been granted status under this subparagraph, the foreign state of which the alien is a national and in which the alien has been domiciled for a continuous period of not less than 3 years at any point before applying for a nonimmigrant visa under this subparagraph), and the spouse and children of any such alien if accompanying or following to join such alien; (i) solely to carry on substantial trade, including trade in services or trade in technology, principally between the United States and the foreign state of which the alien is a national; (ii) solely to develop and direct the operations of an enterprise in which the alien has invested, or of an enterprise in which the alien is actively in the process of investing, a substantial amount of capital; or (iii) solely to perform services in a specialty occupation in the United States if the alien is a national of the Commonwealth of Australia and with respect to whom the Secretary of Labor determines and certifies to the Secretary of Homeland Security and the Secretary of State that the intending employer has filed with the Secretary of Labor an attestation under section 1182(t)(1) of this title;"],[1,"(F)(i) an alien having a residence in a foreign country which he has no intention of abandoning, who is a bona fide student qualified to pursue a full course of study and who seeks to enter the United States temporarily and solely for the purpose of pursuing such a course of study consistent with section 1184(l) 1 of this title at an established college, university, seminary, conservatory, academic high school, elementary school, or other academic institution or in an accredited language training program in the United States, particularly designated by him and approved by the Attorney General after consultation with the Secretary of Education, which institution or place of study shall have agreed to report to the Attorney General the termination of attendance of each nonimmigrant student, and if any such institution of learning or place of study fails to make reports promptly the approval shall be withdrawn, (ii) the alien spouse and minor children of any alien described in clause (i) if accompanying or following to join such an alien, and (iii) an alien who is a national of Canada or Mexico, who maintains actual residence and place of abode in the country of nationality, who is described in clause (i) except that the alien's qualifications for and actual course of study may be full or part-time, and who commutes to the United States institution or place of study from Canada or Mexico;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1101?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1101. Definitions","tname":"Aliens and Nationality","by":{"0":"2, 7, 3, 4","1":"3, 4"}},{"t":"usc","label":"8 U.S.C. § 1227","url":"https://www.law.cornell.edu/uscode/text/8/1227","subs":["(a)(2)(A)(i)","(a)(2)(B)"],"stext":{"head":"§1227. Deportable aliens","paras":[[0,"(a) Classes of deportable aliens"],[0,"Any alien (including an alien crewman) in and admitted to the United States shall, upon the order of the Attorney General, be removed if the alien is within one or more of the following classes of deportable aliens:"],[0,"(1) Inadmissible at time of entry or of adjustment of status or violates status"],[0,"(A) Inadmissible aliens"],[2,"Any alien who at the time of entry or adjustment of status was within one or more of the classes of aliens inadmissible by the law existing at such time is deportable."],[0,"(B) Present in violation of law"],[2,"Any alien who is present in the United States in violation of this chapter or any other law of the United States, or whose nonimmigrant visa (or other documentation authorizing admission into the United States as a nonimmigrant) has been revoked under section 1201(i) of this title, is deportable."],[0,"(C) Violated nonimmigrant status or condition of entry"],[0,"(i) Nonimmigrant status violators"],[3,"Any alien who was admitted as a nonimmigrant and who has failed to maintain the nonimmigrant status in which the alien was admitted or to which it was changed under section 1258 of this title, or to comply with the conditions of any such status, is deportable."],[0,"(ii) Violators of conditions of entry"],[3,"Any alien whom the Secretary of Health and Human Services certifies has failed to comply with terms, conditions, and controls that were imposed under section 1182(g) of this title is deportable."],[0,"(D) Termination of conditional permanent residence"],[0,"(i) In general"],[3,"Any alien with permanent resident status on a conditional basis under section 1186a of this title (relating to conditional permanent resident status for certain alien spouses and sons and daughters) or under section 1186b of this title (relating to conditional permanent resident status for certain alien entrepreneurs, spouses, and children) who has had such status terminated under such respective section is deportable."],[0,"(ii) Exception"],[3,"Clause (i) shall not apply in the cases described in section 1186a(c)(4) of this title (relating to certain hardship waivers)."],[0,"(E) Smuggling"],[0,"(i) In general"],[3,"Any alien who (prior to the date of entry, at the time of any entry, or within 5 years of the date of any entry) knowingly has encouraged, induced, assisted, abetted, or aided any other alien to enter or to try to enter the United States in violation of law is deportable."],[0,"(ii) Special rule in the case of family reunification"],[3,"Clause (i) shall not apply in the case of alien who is an eligible immigrant (as defined in section 301(b)(1) of the Immigration Act of 1990), was physically present in the United States on May 5, 1988, and is seeking admission as an immediate relative or under section 1153(a)(2) of this title (including under section 112 of the Immigration Act of 1990) or benefits under section 301(a) of the Immigration Act of 1990 if the alien, before May 5, 1988, has encouraged, induced, assisted, abetted, or aided only the alien's spouse, parent, son, or daughter (and no other individual) to enter the United States in violation of law."],[0,"(iii) Waiver authorized"],[3,"The Attorney General may, in his discretion for humanitarian purposes, to assure family unity, or when it is otherwise in the public interest, waive application of clause (i) in the case of any alien lawfully admitted for permanent residence if the alien has encouraged, induced, assisted, abetted, or aided only an individual who at the time of the offense was the alien's spouse, parent, son, or daughter (and no other individual) to enter the United States in violation of law."],[0,"(F) Repealed. Pub. L. 104–208, div. C, title VI, §671(d)(1)(C), Sept. 30, 1996, 110 Stat. 3009–723"],[0,"(G) Marriage fraud"],[2,"An alien shall be considered to be deportable as having procured a visa or other documentation by fraud (within the meaning of section 1182(a)(6)(C)(i) of this title) and to be in the United States in violation of this chapter (within the meaning of subparagraph (B)) if—"],[3,"(i) the alien obtains any admission into the United States with an immigrant visa or other documentation procured on the basis of a marriage entered into less than 2 years prior to such admission of the alien and which, within 2 years subsequent to any admission of the alien in the United States, shall be judicially annulled or terminated, unless the alien establishes to the satisfaction of the Attorney General that such marriage was not contracted for the purpose of evading any provisions of the immigration laws, or"],[3,"(ii) it appears to the satisfaction of the Attorney General that the alien has failed or refused to fulfill the alien's marital agreement which in the opinion of the Attorney General was made for the purpose of procuring the alien's admission as an immigrant."],[0,"(H) Waiver authorized for certain misrepresentations"],[2,"The provisions of this paragraph relating to the removal of aliens within the United States on the ground that they were inadmissible at the time of admission as aliens described in section 1182(a)(6)(C)(i) of this title, whether willful or innocent, may, in the discretion of the Attorney General, be waived for any alien (other than an alien described in paragraph (4)(D)) who—"],[3,"(i)(I) is the spouse, parent, son, or daughter of a citizen of the United States or of an alien lawfully admitted to the United States for permanent residence; and"],[3,"(II) was in possession of an immigrant visa or equivalent document and was otherwise admissible to the United States at the time of such admission except for those grounds of inadmissibility specified under paragraphs (5)(A) and (7)(A) of section 1182(a) of this title which were a direct result of that fraud or misrepresentation."],[3,"(ii) is a VAWA self-petitioner."],[2,"A waiver of removal for fraud or misrepresentation granted under this subparagraph shall also operate to waive removal based on the grounds of inadmissibility directly resulting from such fraud or misrepresentation."],[0,"(2) Criminal offenses"],[0,"(A) General crimes"],[0,"(i) Crimes of moral turpitude"],[3,"Any alien who—"],[4,"(I) is convicted of a crime involving moral turpitude committed within five years (or 10 years in the case of an alien provided lawful permanent resident status under section 1255(j) of this title) after the date of admission, and"],[4,"(II) is convicted of a crime for which a sentence of one year or longer may be imposed,"],[0,"is deportable."],[0,"(ii) Multiple criminal convictions"],[3,"Any alien who at any time after admission is convicted of two or more crimes involving moral turpitude, not arising out of a single scheme of criminal misconduct, regardless of whether confined therefor and regardless of whether the convictions were in a single trial, is deportable."],[0,"(iii) Aggravated felony"],[3,"Any alien who is convicted of an aggravated felony at any time after admission is deportable."],[0,"(iv) High speed flight"],[3,"Any alien who is convicted of a violation of section 758 of title 18 (relating to high speed flight from an immigration checkpoint) is deportable."],[0,"(v) Failure to register as a sex offender"],[3,"Any alien who is convicted under section 2250 of title 18 is deportable."],[0,"(vi) Waiver authorized"],[3,"Clauses (i), (ii), (iii), and (iv) shall not apply in the case of an alien with respect to a criminal conviction if the alien subsequent to the criminal conviction has been granted a full and unconditional pardon by the President of the United States or by the Governor of any of the several States."],[0,"(B) Controlled substances"],[0,"(i) Conviction"],[3,"Any alien who at any time after admission has been convicted of a violation of (or a conspiracy or attempt to violate) any law or regulation of a State, the United States, or a foreign country relating to a controlled substance (as defined in section 802 of title 21), other than a single offense involving possession for one's own use of 30 grams or less of marijuana, is deportable."],[0,"(ii) Drug abusers and addicts"],[3,"Any alien who is, or at any time after admission has been, a drug abuser or addict is deportable."],[0,"(C) Certain firearm offenses"],[2,"Any alien who at any time after admission is convicted under any law of purchasing, selling, offering for sale, exchanging, using, owning, possessing, or carrying, or of attempting or conspiring to purchase, sell, offer for sale, exchange, use, own, possess, or carry, any weapon, part, or accessory which is a firearm or destructive device (as defined in section 921(a) of title 18) in violation of any law is deportable."],[0,"(D) Miscellaneous crimes"],[2,"Any alien who at any time has been convicted (the judgment on such conviction becoming final) of, or has been so convicted of a conspiracy or attempt to violate—"],[3,"(i) any offense under chapter 37 (relating to espionage), chapter 105 (relating to sabotage), or chapter 115 (relating to treason and sedition) of title 18 for which a term of imprisonment of five or more years may be imposed;"],[3,"(ii) any offense under section 871 or 960 of title 18;"],[3,"(iii) a violation of any provision of the Military Selective Service Act (50 U.S.C. App. 451 et seq.) [now 50 U.S.C. 3801 et seq.] or the Trading With the Enemy Act (50 U.S.C. App. 1 et seq.) [now 50 U.S.C. 4301 et seq.]; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1227?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1227. Deportable aliens","tname":"Aliens and Nationality","by":{"0":"3, 3","1":"3"}},{"t":"usc","label":"8 U.S.C. § 1228","url":"https://www.law.cornell.edu/uscode/text/8/1228","subs":["(b)","(b)(4)(B)"],"by":{"0":"3, 4"}},{"t":"usc","label":"8 U.S.C. § 1229","url":"https://www.law.cornell.edu/uscode/text/8/1229","subs":["(b)"],"by":{"0":"25"}},{"t":"usc","label":"8 U.S.C. § 1229a","url":"https://www.law.cornell.edu/uscode/text/8/1229a","subs":["(b)(4)","(b)(4)(A)","(c)(5)","(a)(1)","(c)(1)(A)"],"stext":{"head":"§1229a. Removal proceedings","paras":[[0,"(a) Proceeding"],[0,"(1) In general"],[1,"An immigration judge shall conduct proceedings for deciding the inadmissibility or deportability of an alien."],[0,"(2) Charges"],[1,"An alien placed in proceedings under this section may be charged with any applicable ground of inadmissibility under section 1182(a) of this title or any applicable ground of deportability under section 1227(a) of this title."],[0,"(3) Exclusive procedures"],[1,"Unless otherwise specified in this chapter, a proceeding under this section shall be the sole and exclusive procedure for determining whether an alien may be admitted to the United States or, if the alien has been so admitted, removed from the United States. Nothing in this section shall affect proceedings conducted pursuant to section 1228 of this title."],[0,"(b) Conduct of proceeding"],[0,"(1) Authority of immigration judge"],[1,"The immigration judge shall administer oaths, receive evidence, and interrogate, examine, and cross-examine the alien and any witnesses. The immigration judge may issue subpoenas for the attendance of witnesses and presentation of evidence. The immigration judge shall have authority (under regulations prescribed by the Attorney General) to sanction by civil money penalty any action (or inaction) in contempt of the judge's proper exercise of authority under this chapter."],[0,"(2) Form of proceeding"],[0,"(A) In general"],[2,"The proceeding may take place—"],[3,"(i) in person,"],[3,"(ii) where agreed to by the parties, in the absence of the alien,"],[3,"(iii) through video conference, or"],[3,"(iv) subject to subparagraph (B), through telephone conference."],[0,"(B) Consent required in certain cases"],[2,"An evidentiary hearing on the merits may only be conducted through a telephone conference with the consent of the alien involved after the alien has been advised of the right to proceed in person or through video conference."],[0,"(3) Presence of alien"],[1,"If it is impracticable by reason of an alien's mental incompetency for the alien to be present at the proceeding, the Attorney General shall prescribe safeguards to protect the rights and privileges of the alien."],[0,"(4) Alien's rights in proceeding"],[1,"In proceedings under this section, under regulations of the Attorney General—"],[2,"(A) the alien shall have the privilege of being represented, at no expense to the Government, by counsel of the alien's choosing who is authorized to practice in such proceedings,"],[2,"(B) the alien shall have a reasonable opportunity to examine the evidence against the alien, to present evidence on the alien's own behalf, and to cross-examine witnesses presented by the Government but these rights shall not entitle the alien to examine such national security information as the Government may proffer in opposition to the alien's admission to the United States or to an application by the alien for discretionary relief under this chapter, and"],[2,"(C) a complete record shall be kept of all testimony and evidence produced at the proceeding."],[0,"(5) Consequences of failure to appear"],[0,"(A) In general"],[2,"Any alien who, after written notice required under paragraph (1) or (2) of section 1229(a) of this title has been provided to the alien or the alien's counsel of record, does not attend a proceeding under this section, shall be ordered removed in absentia if the Service establishes by clear, unequivocal, and convincing evidence that the written notice was so provided and that the alien is removable (as defined in subsection (e)(2)). The written notice by the Attorney General shall be considered sufficient for purposes of this subparagraph if provided at the most recent address provided under section 1229(a)(1)(F) of this title."],[0,"(B) No notice if failure to provide address information"],[2,"No written notice shall be required under subparagraph (A) if the alien has failed to provide the address required under section 1229(a)(1)(F) of this title."],[0,"(C) Rescission of order"],[2,"Such an order may be rescinded only—"],[3,"(i) upon a motion to reopen filed within 180 days after the date of the order of removal if the alien demonstrates that the failure to appear was because of exceptional circumstances (as defined in subsection (e)(1)), or"],[3,"(ii) upon a motion to reopen filed at any time if the alien demonstrates that the alien did not receive notice in accordance with paragraph (1) or (2) of section 1229(a) of this title or the alien demonstrates that the alien was in Federal or State custody and the failure to appear was through no fault of the alien."],[2,"The filing of the motion to reopen described in clause (i) or (ii) shall stay the removal of the alien pending disposition of the motion by the immigration judge."],[0,"(D) Effect on judicial review"],[2,"Any petition for review under section 1252 of this title of an order entered in absentia under this paragraph shall (except in cases described in section 1252(b)(5) of this title) be confined to (i) the validity of the notice provided to the alien, (ii) the reasons for the alien's not attending the proceeding, and (iii) whether or not the alien is removable."],[0,"(E) Additional application to certain aliens in contiguous territory"],[2,"The preceding provisions of this paragraph shall apply to all aliens placed in proceedings under this section, including any alien who remains in a contiguous foreign territory pursuant to section 1225(b)(2)(C) of this title."],[0,"(6) Treatment of frivolous behavior"],[1,"The Attorney General shall, by regulation—"],[2,"(A) define in a proceeding before an immigration judge or before an appellate administrative body under this subchapter, frivolous behavior for which attorneys may be sanctioned,"],[2,"(B) specify the circumstances under which an administrative appeal of a decision or ruling will be considered frivolous and will be summarily dismissed, and"],[2,"(C) impose appropriate sanctions (which may include suspension and disbarment) in the case of frivolous behavior."],[1,"Nothing in this paragraph shall be construed as limiting the authority of the Attorney General to take actions with respect to inappropriate behavior."],[0,"(7) Limitation on discretionary relief for failure to appear"],[1,"Any alien against whom a final order of removal is entered in absentia under this subsection and who, at the time of the notice described in paragraph (1) or (2) of section 1229(a) of this title, was provided oral notice, either in the alien's native language or in another language the alien understands, of the time and place of the proceedings and of the consequences under this paragraph of failing, other than because of exceptional circumstances (as defined in subsection (e)(1)) to attend a proceeding under this section, shall not be eligible for relief under section 1229b, 1229c, 1255, 1258, or 1259 of this title for a period of 10 years after the date of the entry of the final order of removal."],[0,"(c) Decision and burden of proof"],[0,"(1) Decision"],[0,"(A) In general"],[2,"At the conclusion of the proceeding the immigration judge shall decide whether an alien is removable from the United States. The determination of the immigration judge shall be based only on the evidence produced at the hearing."],[0,"(B) Certain medical decisions"],[2,"If a medical officer or civil surgeon or board of medical officers has certified under section 1222(b) of this title that an alien has a disease, illness, or addiction which would make the alien inadmissible under paragraph (1) of section 1182(a) of this title, the decision of the immigration judge shall be based solely upon such certification."],[0,"(2) Burden on alien"],[1,"In the proceeding the alien has the burden of establishing—"],[2,"(A) if the alien is an applicant for admission, that the alien is clearly and beyond doubt entitled to be admitted and is not inadmissible under section 1182 of this title; or"],[2,"(B) by clear and convincing evidence, that the alien is lawfully present in the United States pursuant to a prior admission."],[1,"In meeting the burden of proof under subparagraph (B), the alien shall have access to the alien's visa or other entry document, if any, and any other records and documents, not considered by the Attorney General to be confidential, pertaining to the alien's admission or presence in the United States."],[0,"(3) Burden on service in cases of deportable aliens"],[0,"(A) In general"],[2,"In the proceeding the Service has the burden of establishing by clear and convincing evidence that, in the case of an alien who has been admitted to the United States, the alien is deportable. No decision on deportability shall be valid unless it is based upon reasonable, substantial, and probative evidence."],[0,"(B) Proof of convictions"],[2,"In any proceeding under this chapter, any of the following documents or records (or a certified copy of such an official document or record) shall constitute proof of a criminal conviction:"],[3,"(i) An official record of judgment and conviction."],[3,"(ii) An official record of plea, verdict, and sentence."],[3,"(iii) A docket entry from court records that indicates the existence of the conviction."],[3,"(iv) Official minutes of a court proceeding or a transcript of a court hearing in which the court takes notice of the existence of the conviction."],[3,"(v) An abstract of a record of conviction prepared by the court in which the conviction was entered, or by a State official associated with the State's repository of criminal justice records, that indicates the charge or section of law violated, the disposition of the case, the existence and date of conviction, and the sentence."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1229a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1229a. Removal proceedings","tname":"Aliens and Nationality","by":{"0":"3, 4, 25, 4, 25","1":"20","2":"10, 10"}},{"t":"usc","label":"8 U.S.C. § 1229b","url":"https://www.law.cornell.edu/uscode/text/8/1229b","subs":["(a)(3)"],"by":{"0":"19"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","subs":["(a)","(d)","(b)(2)"],"stext":{"head":"§1252. Judicial review of orders of removal","paras":[[0,"(a) Applicable provisions"],[0,"(1) General orders of removal"],[1,"Judicial review of a final order of removal (other than an order of removal without a hearing pursuant to section 1225(b)(1) of this title) is governed only by chapter 158 of title 28, except as provided in subsection (b) and except that the court may not order the taking of additional evidence under section 2347(c) of such title."],[0,"(2) Matters not subject to judicial review"],[0,"(A) Review relating to section 1225(b)(1)"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, no court shall have jurisdiction to review—"],[3,"(i) except as provided in subsection (e), any individual determination or to entertain any other cause or claim arising from or relating to the implementation or operation of an order of removal pursuant to section 1225(b)(1) of this title,"],[3,"(ii) except as provided in subsection (e), a decision by the Attorney General to invoke the provisions of such section,"],[3,"(iii) the application of such section to individual aliens, including the determination made under section 1225(b)(1)(B) of this title, or"],[3,"(iv) except as provided in subsection (e), procedures and policies adopted by the Attorney General to implement the provisions of section 1225(b)(1) of this title."],[0,"(B) Denials of discretionary relief"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), and regardless of whether the judgment, decision, or action is made in removal proceedings, no court shall have jurisdiction to review—"],[3,"(i) any judgment regarding the granting of relief under section 1182(h), 1182(i), 1229b, 1229c, or 1255 of this title, or"],[3,"(ii) any other decision or action of the Attorney General or the Secretary of Homeland Security the authority for which is specified under this subchapter to be in the discretion of the Attorney General or the Secretary of Homeland Security, other than the granting of relief under section 1158(a) of this title."],[0,"(C) Orders against criminal aliens"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), no court shall have jurisdiction to review any final order of removal against an alien who is removable by reason of having committed a criminal offense covered in section 1182(a)(2) or 1227(a)(2)(A)(iii), (B), (C), or (D) of this title, or any offense covered by section 1227(a)(2)(A)(ii) of this title for which both predicate offenses are, without regard to their date of commission, otherwise covered by section 1227(a)(2)(A)(i) of this title."],[0,"(D) Judicial review of certain legal claims"],[2,"Nothing in subparagraph (B) or (C), or in any other provision of this chapter (other than this section) which limits or eliminates judicial review, shall be construed as precluding review of constitutional claims or questions of law raised upon a petition for review filed with an appropriate court of appeals in accordance with this section."],[0,"(3) Treatment of certain decisions"],[1,"No alien shall have a right to appeal from a decision of an immigration judge which is based solely on a certification described in section 1229a(c)(1)(B) of this title."],[0,"(4) Claims under the United Nations Convention"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of any cause or claim under the United Nations Convention Against Torture and Other Forms of Cruel, Inhuman, or Degrading Treatment or Punishment, except as provided in subsection (e)."],[0,"(5) Exclusive means of review"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of an order of removal entered or issued under any provision of this chapter, except as provided in subsection (e). For purposes of this chapter, in every provision that limits or eliminates judicial review or jurisdiction to review, the terms \"judicial review\" and \"jurisdiction to review\" include habeas corpus review pursuant to section 2241 of title 28, or any other habeas corpus provision, sections 1361 and 1651 of such title, and review pursuant to any other provision of law (statutory or nonstatutory)."],[0,"(b) Requirements for review of orders of removal"],[0,"With respect to review of an order of removal under subsection (a)(1), the following requirements apply:"],[0,"(1) Deadline"],[1,"The petition for review must be filed not later than 30 days after the date of the final order of removal."],[0,"(2) Venue and forms"],[1,"The petition for review shall be filed with the court of appeals for the judicial circuit in which the immigration judge completed the proceedings. The record and briefs do not have to be printed. The court of appeals shall review the proceeding on a typewritten record and on typewritten briefs."],[0,"(3) Service"],[0,"(A) In general"],[2,"The respondent is the Attorney General. The petition shall be served on the Attorney General and on the officer or employee of the Service in charge of the Service district in which the final order of removal under section 1229a of this title was entered."],[0,"(B) Stay of order"],[2,"Service of the petition on the officer or employee does not stay the removal of an alien pending the court's decision on the petition, unless the court orders otherwise."],[0,"(C) Alien's brief"],[2,"The alien shall serve and file a brief in connection with a petition for judicial review not later than 40 days after the date on which the administrative record is available, and may serve and file a reply brief not later than 14 days after service of the brief of the Attorney General, and the court may not extend these deadlines except upon motion for good cause shown. If an alien fails to file a brief within the time provided in this paragraph, the court shall dismiss the appeal unless a manifest injustice would result."],[0,"(4) Scope and standard for review"],[1,"Except as provided in paragraph (5)(B)—"],[2,"(A) the court of appeals shall decide the petition only on the administrative record on which the order of removal is based,"],[2,"(B) the administrative findings of fact are conclusive unless any reasonable adjudicator would be compelled to conclude to the contrary,"],[2,"(C) a decision that an alien is not eligible for admission to the United States is conclusive unless manifestly contrary to law, and"],[2,"(D) the Attorney General's discretionary judgment whether to grant relief under section 1158(a) of this title shall be conclusive unless manifestly contrary to the law and an abuse of discretion."],[1,"No court shall reverse a determination made by a trier of fact with respect to the availability of corroborating evidence, as described in section 1158(b)(1)(B), 1229a(c)(4)(B), or 1231(b)(3)(C) of this title, unless the court finds, pursuant to subsection (b)(4)(B), that a reasonable trier of fact is compelled to conclude that such corroborating evidence is unavailable."],[0,"(5) Treatment of nationality claims"],[0,"(A) Court determination if no issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds from the pleadings and affidavits that no genuine issue of material fact about the petitioner's nationality is presented, the court shall decide the nationality claim."],[0,"(B) Transfer if issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds that a genuine issue of material fact about the petitioner's nationality is presented, the court shall transfer the proceeding to the district court of the United States for the judicial district in which the petitioner resides for a new hearing on the nationality claim and a decision on that claim as if an action had been brought in the district court under section 2201 of title 28."],[0,"(C) Limitation on determination"],[2,"The petitioner may have such nationality claim decided only as provided in this paragraph."],[0,"(6) Consolidation with review of motions to reopen or reconsider"],[1,"When a petitioner seeks review of an order under this section, any review sought of a motion to reopen or reconsider the order shall be consolidated with the review of the order."],[0,"(7) Challenge to validity of orders in certain criminal proceedings"],[0,"(A) In general"],[2,"If the validity of an order of removal has not been judicially decided, a defendant in a criminal proceeding charged with violating section 1253(a) of this title may challenge the validity of the order in the criminal proceeding only by filing a separate motion before trial. The district court, without a jury, shall decide the motion before trial."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1252?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1252. Judicial review of orders of removal","tname":"Aliens and Nationality","by":{"0":"4, 4","1":"4, 25, 45, 49","2":"7"}},{"t":"usc","label":"8 U.S.C. § 1326","url":"https://www.law.cornell.edu/uscode/text/8/1326","subs":["(1952)","(a)","(a)(1)","(b)","(d)","(d)(1)","(d)(2)","(d)(3)","(1)(1952)"],"stext":{"head":"§1326. Reentry of removed aliens","paras":[[0,"(a) In general"],[0,"Subject to subsection (b), any alien who—"],[1,"(1) has been denied admission, excluded, deported, or removed or has departed the United States while an order of exclusion, deportation, or removal is outstanding, and thereafter"],[1,"(2) enters, attempts to enter, or is at any time found in, the United States, unless (A) prior to his reembarkation at a place outside the United States or his application for admission from foreign contiguous territory, the Attorney General has expressly consented to such alien's reapplying for admission; or (B) with respect to an alien previously denied admission and removed, unless such alien shall establish that he was not required to obtain such advance consent under this chapter or any prior Act,"],[0,"shall be fined under title 18, or imprisoned not more than 2 years, or both."],[0,"(b) Criminal penalties for reentry of certain removed aliens"],[0,"Notwithstanding subsection (a), in the case of any alien described in such subsection—"],[1,"(1) whose removal was subsequent to a conviction for commission of three or more misdemeanors involving drugs, crimes against the person, or both, or a felony (other than an aggravated felony), such alien shall be fined under title 18, imprisoned not more than 10 years, or both;"],[1,"(2) whose removal was subsequent to a conviction for commission of an aggravated felony, such alien shall be fined under such title, imprisoned not more than 20 years, or both;"],[1,"(3) who has been excluded from the United States pursuant to section 1225(c) of this title because the alien was excludable under section 1182(a)(3)(B) of this title or who has been removed from the United States pursuant to the provisions of subchapter V, and who thereafter, without the permission of the Attorney General, enters the United States, or attempts to do so, shall be fined under title 18 and imprisoned for a period of 10 years, which sentence shall not run concurrently with any other sentence.1 or"],[1,"(4) who was removed from the United States pursuant to section 1231(a)(4)(B) of this title who thereafter, without the permission of the Attorney General, enters, attempts to enter, or is at any time found in, the United States (unless the Attorney General has expressly consented to such alien's reentry) shall be fined under title 18, imprisoned for not more than 10 years, or both."],[0,"For the purposes of this subsection, the term \"removal\" includes any agreement in which an alien stipulates to removal during (or not during) a criminal trial under either Federal or State law."],[0,"(c) Reentry of alien deported prior to completion of term of imprisonment"],[0,"Any alien deported pursuant to section 1252(h)(2) 2 of this title who enters, attempts to enter, or is at any time found in, the United States (unless the Attorney General has expressly consented to such alien's reentry) shall be incarcerated for the remainder of the sentence of imprisonment which was pending at the time of deportation without any reduction for parole or supervised release. Such alien shall be subject to such other penalties relating to the reentry of deported aliens as may be available under this section or any other provision of law."],[0,"(d) Limitation on collateral attack on underlying deportation order"],[0,"In a criminal proceeding under this section, an alien may not challenge the validity of the deportation order described in subsection (a)(1) or subsection (b) unless the alien demonstrates that—"],[1,"(1) the alien exhausted any administrative remedies that may have been available to seek relief against the order;"],[1,"(2) the deportation proceedings at which the order was issued improperly deprived the alien of the opportunity for judicial review; and"],[1,"(3) the entry of the order was fundamentally unfair."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1326?type=usc&year=mostrecent&link-type=html"},"op":3,"ar":5,"head":"§1326. Reentry of removed aliens","tname":"Aliens and Nationality","by":{"0":"25, 25, 25, 25, 25, 25, 25, 25, 25","1":"passim, 4","2":"9, 11, 12, 22, 9, 21, passim, 1, 2, 11, 14, 23, 1, 2, 6, 14, 23, 23"}},{"t":"usc","label":"8 U.S.C. § 1362","url":"https://www.law.cornell.edu/uscode/text/8/1362","by":{"0":"25"}},{"t":"usc","label":"18 U.S.C. § 3601","url":"https://www.law.cornell.edu/uscode/text/18/3601","by":{"0":"22"}},{"t":"usc","label":"18 U.S.C. § 16","url":"https://www.law.cornell.edu/uscode/text/18/16","subs":["(b)"],"stext":{"head":"§16. Crime of violence defined","paras":[[0,"The term \"crime of violence\" means—"],[1,"(a) an offense that has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(b) any other offense that is a felony and that, by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/16?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§16. Crime of violence defined","tname":"Crimes and Criminal Procedure","by":{"0":"3, 3, 7, 8","1":"21, 38"}},{"t":"usc","label":"18 U.S.C. § 1201","url":"https://www.law.cornell.edu/uscode/text/18/1201","subs":["(a)"],"by":{"0":"20"}},{"t":"usc","label":"28 U.S.C. § 2255","url":"https://www.law.cornell.edu/uscode/text/28/2255","by":{"0":"21"}},{"t":"usc","label":"42 U.S.C. § 1997e","url":"https://www.law.cornell.edu/uscode/text/42/1997e","subs":["(a)"],"stext":{"head":"§1997e. Suits by prisoners","paras":[[0,"(a) Applicability of administrative remedies"],[0,"No action shall be brought with respect to prison conditions under section 1983 of this title, or any other Federal law, by a prisoner confined in any jail, prison, or other correctional facility until such administrative remedies as are available are exhausted."],[0,"(b) Failure of State to adopt or adhere to administrative grievance procedure"],[0,"The failure of a State to adopt or adhere to an administrative grievance procedure shall not constitute the basis for an action under section 1997a or 1997c of this title."],[0,"(c) Dismissal"],[0,"(1) The court shall on its own motion or on the motion of a party dismiss any action brought with respect to prison conditions under section 1983 of this title, or any other Federal law, by a prisoner confined in any jail, prison, or other correctional facility if the court is satisfied that the action is frivolous, malicious, fails to state a claim upon which relief can be granted, or seeks monetary relief from a defendant who is immune from such relief."],[0,"(2) In the event that a claim is, on its face, frivolous, malicious, fails to state a claim upon which relief can be granted, or seeks monetary relief from a defendant who is immune from such relief, the court may dismiss the underlying claim without first requiring the exhaustion of administrative remedies."],[0,"(d) Attorney's fees"],[0,"(1) In any action brought by a prisoner who is confined to any jail, prison, or other correctional facility, in which attorney's fees are authorized under section 1988 1 of this title, such fees shall not be awarded, except to the extent that—"],[1,"(A) the fee was directly and reasonably incurred in proving an actual violation of the plaintiff's rights protected by a statute pursuant to which a fee may be awarded under section 1988 1 of this title; and"],[1,"(B)(i) the amount of the fee is proportionately related to the court ordered relief for the violation; or"],[1,"(ii) the fee was directly and reasonably incurred in enforcing the relief ordered for the violation."],[0,"(2) Whenever a monetary judgment is awarded in an action described in paragraph (1), a portion of the judgment (not to exceed 25 percent) shall be applied to satisfy the amount of attorney's fees awarded against the defendant. If the award of attorney's fees is not greater than 150 percent of the judgment, the excess shall be paid by the defendant."],[0,"(3) No award of attorney's fees in an action described in paragraph (1) shall be based on an hourly rate greater than 150 percent of the hourly rate established under section 3006A of title 18 for payment of court-appointed counsel."],[0,"(4) Nothing in this subsection shall prohibit a prisoner from entering into an agreement to pay an attorney's fee in an amount greater than the amount authorized under this subsection, if the fee is paid by the individual rather than by the defendant pursuant to section 1988 1 of this title."],[0,"(e) Limitation on recovery"],[0,"No Federal civil action may be brought by a prisoner confined in a jail, prison, or other correctional facility, for mental or emotional injury suffered while in custody without a prior showing of physical injury or the commission of a sexual act (as defined in section 2246 of title 18)."],[0,"(f) Hearings"],[0,"(1) To the extent practicable, in any action brought with respect to prison conditions in Federal court pursuant to section 1983 of this title, or any other Federal law, by a prisoner confined in any jail, prison, or other correctional facility, pretrial proceedings in which the prisoner's participation is required or permitted shall be conducted by telephone, video conference, or other telecommunications technology without removing the prisoner from the facility in which the prisoner is confined."],[0,"(2) Subject to the agreement of the official of the Federal, State, or local unit of government with custody over the prisoner, hearings may be conducted at the facility in which the prisoner is confined. To the extent practicable, the court shall allow counsel to participate by telephone, video conference, or other communications technology in any hearing held at the facility."],[0,"(g) Waiver of reply"],[0,"(1) Any defendant may waive the right to reply to any action brought by a prisoner confined in any jail, prison, or other correctional facility under section 1983 of this title or any other Federal law. Notwithstanding any other law or rule of procedure, such waiver shall not constitute an admission of the allegations contained in the complaint. No relief shall be granted to the plaintiff unless a reply has been filed."],[0,"(2) The court may require any defendant to reply to a complaint brought under this section if it finds that the plaintiff has a reasonable opportunity to prevail on the merits."],[0,"(h) \"Prisoner\" defined"],[0,"As used in this section, the term \"prisoner\" means any person incarcerated or detained in any facility who is accused of, convicted of, sentenced for, or adjudicated delinquent for, violations of criminal law or the terms and conditions of parole, probation, pretrial release, or diversionary program."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1997e?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1997e. Suits by prisoners","tname":"The Public Health and Welfare","by":{"0":"22"}},{"t":"case","label":"Adamo Wrecking Co. v. United States","cite":"434 U.S. 275","y":1978,"id":"1977/76-911","sc":1,"sum":"The Clean Air Act authorizes the Administrator of the Environmental Protection Agency (EPA) to promulgate \"emission standards\" for hazardous air pollutants. The emission of an air pollutant in violation of an applicable emission standard is prohibited by § 112 (c) (1) (B), the knowing violation of which is made a criminal offense by § 113 (c) (1) (C). Section 307 (b) (1) provides that a petition for review of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Allen v. Ives","cite":"950 F.3d 1184","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/950/1184/","by":{"1":"26"}},{"t":"case","label":"Andres v. Marshall","cite":"867 F.3d 1076","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/867/1076/","by":{"1":"44"}},{"t":"case","label":"Barron v. Ashcroft","cite":"358 F.3d 674","y":2004,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/358/674/","by":{"1":"45"}},{"t":"case","label":"Batrez Gradiz v. Gonzales","cite":"490 F.3d 1206","y":2007,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/490/1206/","by":{"1":"25"}},{"t":"case","label":"Bennett v. Spear","cite":"520 U.S. 154","y":1997,"id":"1996/95-813","sc":1,"sum":"In the unanimous decision, announced by Justice Antonin Scalia, the Court ruled that the petitioners had standing to ask for judicial review of the minimum water level setting under the Endangered Species Act. The Act explicitly allows \"any person\" to sue the government over an alleged violation. Justice Scalia asserted this applies to the Secretary's actions over enforcement.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Bowen v. City of New York","cite":"476 U.S. 467","y":1986,"id":"1985/84-1923","sc":1,"sum":"The Social Security Act provides benefits to disabled persons under two programs administered by the Social Security Administration (SSA): the Social Security Disability Insurance Program (SSD) and the Supplemental Security Income Program (SSI). Regulations for both programs establish a five-step \"sequential evaluation\" process for determining eligibility for benefits. The initial determination of whether an …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"35"}},{"t":"case","label":"Boykin v. Alabama","cite":"395 U.S. 238","y":1969,"id":"1968/642","sc":1,"sum":"The Court held that a guilty plea is a confession, and the admissibility of a confession is contingent on the confirmation that it was made voluntarily. The waiver of several constitutional rights is involved in a guilty plea. A defendant’s silence is insufficient to show that he understood these rights and chose to waive them.","sumSrc":"Oyez","by":{"1":"37","2":"6"}},{"t":"case","label":"Boynton v. Virginia","cite":"364 U.S. 454","y":1960,"id":"1960/7","sc":1,"sum":"The Court held that the conviction of an interstate bus passenger for refusing to leave the premises of a segregated restaurant violated the Interstate Commerce Act.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"Cardenas-Delgado v. Holder","cite":"720 F.3d 1111","y":2013,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/720/1111/","by":{"1":"11"}},{"t":"case","label":"Chrysler Corp. v. EPA","cite":"600 F.2d 904","y":1979,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/600/904/","sum":"Noting “nagging presence of a substantial due process question” in such a scheme.","sumSrc":"brief:1","by":{"1":"19"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"1":"14"}},{"t":"case","label":"Davis v. United States","cite":"417 U.S. 333","y":1974,"id":"1973/72-1454","sc":1,"sum":"The Court held that Davis could challenge his conviction under 28 U.S.C. Section 2255.","sumSrc":"Oyez","by":{"1":"22, 24"}},{"t":"case","label":"Estep v. United States","cite":"327 U.S. 114","y":1946,"id":"scdb/1945-055","sc":1,"sum":"1. In a criminal prosecution under the Selective Training and Service Act of 1940 for wilfully failing and refusing to submit to induction, a registrant who appeared at the induction center and was finally accepted, but who refused to submit to induction-having pursued his administrative remedy to the end-may interpose the defense that the action of his local board in rejecting his claim of exemption as a minister …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17","2":"20"}},{"t":"case","label":"Fiore v. White","cite":"531 U.S. 225","y":2001,"id":"1999/98-942","sc":1,"sum":"After certifying an question of state law to the Pennsylvania Supreme Court, the U.S. Supreme Court held that Fiore's conviction was not covered by the statute at issue and thus violated the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"1":"2, 22, 24","2":"21"}},{"t":"case","label":"Fry v. United States","cite":"421 U.S. 542","y":1975,"id":"1974/73-822","sc":1,"sum":"The Economic Stabilization Act of 1970 authorized the President to stabilize wages and salaries at certain levels, and the Pay Board was created to oversee the controls. The Government filed this action to enjoin Ohio and its officials from paying state statutory wage and salary increases to state employees above the amount authorized by the Pay Board. The Temporary Emergency Court of Appeals, on certification from …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13"}},{"t":"case","label":"Georgison v. Donelli","cite":"588 F.3d 145","y":2009,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/588/145/","by":{"1":"25"}},{"t":"case","label":"Gutierrez-Brizuela v. Lynch","cite":"834 F.3d 1142","y":2016,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/834/1142/","by":{"1":"45"}},{"t":"case","label":"Henderson v. Morgan","cite":"426 U.S. 637","y":1976,"id":"1975/74-1529","sc":1,"sum":"Since respondent did not receive adequate notice of the offense to which he pleaded guilty, his plea was involuntary and the judgment of conviction was entered without due process of law. The plea could not be voluntary in the sense that it constituted an intelligent admission that he committed the offense unless respondent received \"real notice of the true nature of the charge against him, the first and most …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"37","2":"6"}},{"t":"case","label":"Holland v. Florida","cite":"560 U.S. 631","y":2010,"id":"2009/09-5327","sc":1,"sum":"The Court held that a state prisoner who has exhausted their appeals process in their state has one year to file a writ of habeas corpus, with certain exceptions (including attorney misconduct) that may allow the courts to relax that deadline.","sumSrc":"Oyez","by":{"1":"14"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"1":"11, 14"}},{"t":"case","label":"James v. Gonzales","cite":"464 F.3d 505","y":2006,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/464/505/","by":{"1":"20"}},{"t":"case","label":"Johnson v. Ashcroft","cite":"378 F.3d 164","y":2004,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/378/164/","by":{"1":"41"}},{"t":"case","label":"Johnson v. Zerbst","cite":"304 U.S. 458","y":1938,"id":"scdb/1937-168","sc":1,"sum":"1. A person charged with crime in a federal court is entitled by the Sixth Amendment to the assistance of counsel for his defense.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"42"}},{"t":"case","label":"Lee v. Lampert","cite":"653 F.3d 929","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/653/929/","by":{"1":"24"}},{"t":"case","label":"Magwood v. Patterson","cite":"561 U.S. 320","y":2010,"id":"2009/09-158","sc":1,"sum":"The Court held that, when a habeas corpus application alleges new judgment for the first time, it is not \"second or successive\" under the Antiterrorism and Effective Death Penalty Act and is therefore constitutional.","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"McQuiggin v. Perkins","cite":"569 U.S. 383","y":2013,"id":"2012/12-126","sc":1,"sum":"The Court held that proving actual innocence allows a petitioner to pursue habeas corpus relief regardless of a statute of limitations.","sumSrc":"Oyez","by":{"1":"25, 38","2":"21, 22"}},{"t":"case","label":"Mejia Galindo v. Sessions","cite":"897 F.3d 894","y":2018,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/897/894/","by":{"1":"20"}},{"t":"case","label":"Miller v. French","cite":"530 U.S. 327","y":2000,"id":"1999/99-224","sc":1,"sum":"The Court held that Congress clearly intended to make operation of the PLRA's automatic stay provision mandatory, precluding courts from exercising their equitable power to enjoin the stay and that the PLRA does not violate separation of powers principles.","sumSrc":"Oyez","by":{"1":"14","2":"22"}},{"t":"case","label":"Miller v. Marr","cite":"141 F.3d 976","y":1998,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/141/976/","by":{"1":"24"}},{"t":"case","label":"Montgomery v. Louisiana","cite":"136 S. Ct. 718","y":2016,"id":"2015/14-280","sc":1,"sum":"The Court held that the Supreme Court’s decision in Miller v. Alabama, which prohibits sentencing schemes that impose a punishment of mandatory life without parole for juvenile offenders convicted of homicide, applied retroactively.","sumSrc":"Oyez","by":{"1":"22, 28, 29"}},{"t":"case","label":"Morissette v. United States","cite":"342 U.S. 246","y":1952,"id":"scdb/1951-028","sc":1,"sum":"1. A criminal intent is an essential element of an offense under 18 U. S. C. § 641, which provides that \"whoever embezzles, steals, purloins, or knowingly converts\" property -of the United States is punishable by fine and imprisonment.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"14"}},{"t":"case","label":"Noriega-Lopez v. Ashcroft","cite":"335 F.3d 874","y":2003,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/335/874/","by":{"1":"20"}},{"t":"case","label":"Padilla v. Kentucky","cite":"559 U.S. 356","y":2010,"id":"2009/08-651","sc":1,"sum":"The Court held that counsel must inform a client whether or not his plea carries a risk of deportation under the Sixth Amendment.","sumSrc":"Oyez","by":{"1":"40, 41"}},{"t":"case","label":"Patel v. Ashcroft","cite":"401 F.3d 400","y":2005,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/401/400/","by":{"1":"45"}},{"t":"case","label":"Plaut v. Spendthrift Farm, Inc.","cite":"514 U.S. 211","y":1995,"id":"1994/93-1121","sc":1,"sum":"The Court concluded that Congress had usurped power assigned to the judiciary by Article III and thus had violated the separation of powers principle.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"Rhodes-Bradford v. Keisler","cite":"507 F.3d 77","y":2007,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/507/77/","by":{"1":"20"}},{"t":"case","label":"Rivas v. Fischer","cite":"687 F.3d 514","y":2012,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/687/514/","by":{"1":"24"}},{"t":"case","label":"Rivers v. Roadway Express Inc.","cite":"511 U.S. 298","y":1994,"id":"1993/92-938","sc":1,"op":1,"sum":"Section 101 does not apply to a case that arose before it was enacted.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"1, 21","2":"10"}},{"t":"case","label":"Skilling v. United States","cite":"561 U.S. 358","y":2010,"id":"2009/08-1394","sc":1,"sum":"The Court held that the former CEO of Enron received a fair trial before an impartial jury, and that the federal law that makes it a crime to deprive someone of a fair and honest trial only applies to bribery and kickback schemes.","sumSrc":"Oyez","by":{"1":"46"}},{"t":"case","label":"Souter v. Jones","cite":"395 F.3d 577","y":2005,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/395/577/","by":{"1":"24"}},{"t":"case","label":"Tapia Garcia v. INS","cite":"237 F.3d 1216","y":2001,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/237/1216/","by":{"1":"41"}},{"t":"case","label":"United States v. Attar","cite":"38 F.3d 727","y":1994,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/38/727/","by":{"1":"39"}},{"t":"case","label":"United States v. Balde","cite":"943 F.3d 73","y":2019,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/943/73/","by":{"1":"39"}},{"t":"case","label":"United States v. Bass","cite":"404 U.S. 336","y":1971,"id":"1971/70-71","sc":1,"sum":"It is not clear from the language and legislative history of § 1202 (a) (1) whether or not receipt or possession of a firearm by a convicted felon has to be shown in an individual prosecution to have been connected with interstate commerce. The ambiguity of this provision (which is not only a criminal statute but one whose broad construction would define as a federal offense conduct readily proscribed by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"46"}},{"t":"case","label":"United States v. Copeland","cite":"376 F.3d 61","y":2004,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/376/61/","by":{"1":"35, 41","2":"4, 16"}},{"t":"case","label":"United States v. Davis","cite":"139 S. Ct. 2319","y":2019,"id":"2018/18-431","sc":1,"sum":"Title 18 U. S. C. §924(c)(3)(B), which provides enhanced penalties for using a firearm during a “crime of violence,” is unconstitutionally vague.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"46"}},{"t":"case","label":"United States v. Doctor","cite":"842 F.3d 306","y":2016,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/842/306/","by":{"1":"41"}},{"t":"case","label":"United States v. England","cite":"347 F.2d 425","y":1965,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/347/425/","by":{"1":"17"}},{"t":"case","label":"United States v. Henderson","cite":"906 F.3d 1109","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/906/1109/","by":{"1":"20"}},{"t":"case","label":"United States v. Horton","cite":"863 F.3d 1041","y":2017,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/863/1041/","by":{"1":"20"}},{"t":"case","label":"United States v. Jin Fuey Moy","cite":"241 U.S. 394","y":1916,"id":"scdb/1915-167","sc":1,"op":1,"sum":"A statute must be so construed, if fairly possible, as to avoid not only the conclusion that it is unconstitutional, but also grave doubts upon that score. United States v. Delaware & Hudson Co., 213 TJ. S. 366.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"14"}},{"t":"case","label":"United States v. Johnson","cite":"457 U.S. 537","y":1982,"id":"1981/80-1608","sc":1,"sum":"A decision of this Court construing the Fourth Amendment is to be applied retroactively to all convictions that were not yet final at the time the decision was rendered, except where a case would be clearly controlled by existing retroactivity precedents. Hence, Payton is to be applied retroactively to respondent's case.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22"}},{"t":"case","label":"United States v. Krueger","cite":"809 F.3d 1109","y":2015,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/809/1109/","by":{"1":"19","2":"10"}},{"t":"case","label":"United States v. Leon","cite":"468 U.S. 897","y":1984,"id":"1983/82-1771","sc":1,"sum":"The Court ruled that there is an exception to the exclusionary rule for evidence gathered in \"good faith.\"","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"United States v. Rivera-Nevarez","cite":"418 F.3d 1104","y":2005,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/418/1104/","op":1,"by":{"1":"21"}},{"t":"case","label":"United States v. Saade","cite":"652 F.2d 1126","y":1981,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/652/1126/","by":{"1":"18"}},{"t":"case","label":"United States v. Santos","cite":"553 U.S. 507","y":2008,"id":"2007/06-1005","sc":1,"sum":"Splitting 5 to 4, the Court affirmed the Seventh Circuit, answering that \"proceeds\" refers to \"net income\" or profits and not to \"gross income.\" Because the statute nowhere defines the term \"proceeds\", the plurality applied the so-called rule of lenity which requires such ambiguous statutes to be interpreted in favor of defendants.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"United States v. Spector","cite":"343 U.S. 169","y":1952,"id":"scdb/1951-066","sc":1,"ar":1,"sum":"1. Section 20 (c) of the Immigration Act of 1917, as amended, 8 U. S. C. § 156 (c), which makes it a felony for an alien against whom a specified order of deportation is outstanding to \"willfully fail or refuse to make timely application in good faith for travel or other documents necessary to his departure\" is not, on its face, void for vagueness.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"5, 16, 17, 19","2":"19, 20"}},{"t":"case","label":"United States v. Werdene","cite":"883 F.3d 204","y":2018,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/883/204/","by":{"1":"20"}},{"t":"case","label":"United States v. Witkovich","cite":"353 U.S. 194","y":1957,"id":"1956/295","sc":1,"sum":"Construing clause (3) of § 242 (d) in the context of the entire Section and of the scheme of the legislation as a whole, with due regard to the principle of so construing statutes as to avoid raising constitutional questions, the information an alien is required to furnish under clause (3) relates solely to his availability for deportation; and dismissal of the indictment for failure to state an offense is …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"14"}},{"t":"case","label":"Valentine v. Collier","cite":"141 S. Ct. 57","y":2020,"url":"https://www.courtlistener.com/c/S.%20Ct./141/57/","sc":1,"by":{"1":"35"}},{"t":"case","label":"Vance v. Terrazas","cite":"444 U.S. 252","y":1980,"id":"1979/78-1143","sc":1,"sum":"Section 349 (a) (2) of the Immigration and Nationality Act provides that \"a person who is a national of the United States whether by birth or naturalization, shall lose his nationality by...taking an oath or making an affirmation or other formal declaration of allegiance to a foreign state or a political subdivision thereof.\" Section 349 (c) provides that the party claiming that such loss of citizenship occurred …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13","2":"7"}},{"t":"case","label":"Williams v. Priatno","cite":"829 F.3d 118","y":2016,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/829/118/","by":{"1":"43"}},{"t":"case","label":"Woodford v. Ngo","cite":"548 U.S. 81","y":2006,"id":"2005/05-416","sc":1,"sum":"In a 6-to-3 decision authored by Justice Samuel Alito, the Supreme Court held that a prisoner must properly exhaust any available administrative remedies before bringing suit in federal court. This understanding of the PLRA's exhaustion provision mirrors that of the traditional exhaustion provision in administrative law and is \"substantively similar\" to that of habeas corpus law.","sumSrc":"Oyez","by":{"1":"44"}},{"t":"case","label":"Wyzykowski v. Dep’t of Corr.","cite":"226 F.3d 1213","y":2000,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/226/1213/","by":{"1":"24"}},{"t":"case","label":"Zadvydas v. Davis","cite":"533 U.S. 678","y":2001,"id":"2000/99-7791","sc":1,"sum":"The Court held that \"the statute, read in light of the Constitution's demands, limits an alien's post-removal-period detention to a period reasonably necessary to bring about that alien's removal from the United States\" and \"does not permit indefinite detention.\" \"Based on our conclusion that indefinite detention of aliens in the former category would raise serious constitutional concerns, we construe the statute to contain an implicit 'reasonable time' limitation, the application of which is subject to federal court review,\" wrote Justice Breyer.","sumSrc":"Oyez","by":{"1":"14"}},{"t":"usc","label":"8 U.S.C. § 1325","url":"https://www.law.cornell.edu/uscode/text/8/1325","stext":{"head":"§1325. Improper entry by alien","paras":[[0,"(a) Improper time or place; avoidance of examination or inspection; misrepresentation and concealment of facts"],[0,"Any alien who (1) enters or attempts to enter the United States at any time or place other than as designated by immigration officers, or (2) eludes examination or inspection by immigration officers, or (3) attempts to enter or obtains entry to the United States by a willfully false or misleading representation or the willful concealment of a material fact, shall, for the first commission of any such offense, be fined under title 18 or imprisoned not more than 6 months, or both, and, for a subsequent commission of any such offense, be fined under title 18, or imprisoned not more than 2 years, or both."],[0,"(b) Improper time or place; civil penalties"],[0,"Any alien who is apprehended while entering (or attempting to enter) the United States at a time or place other than as designated by immigration officers shall be subject to a civil penalty of—"],[1,"(1) at least $50 and not more than $250 for each such entry (or attempted entry); or"],[1,"(2) twice the amount specified in paragraph (1) in the case of an alien who has been previously subject to a civil penalty under this subsection."],[0,"Civil penalties under this subsection are in addition to, and not in lieu of, any criminal or other civil penalties that may be imposed."],[0,"(c) Marriage fraud"],[0,"Any individual who knowingly enters into a marriage for the purpose of evading any provision of the immigration laws shall be imprisoned for not more than 5 years, or fined not more than $250,000, or both."],[0,"(d) Immigration-related entrepreneurship fraud"],[0,"Any individual who knowingly establishes a commercial enterprise for the purpose of evading any provision of the immigration laws shall be imprisoned for not more than 5 years, fined in accordance with title 18, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1325?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§1325. Improper entry by alien","tname":"Aliens and Nationality","by":{"1":"2, 3, 50","2":"10"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","by":{"1":"37"}},{"t":"usc","label":"28 U.S.C. § 2254","url":"https://www.law.cornell.edu/uscode/text/28/2254","by":{"1":"25"}},{"t":"reg","label":"8 C.F.R. § 1003.1","url":"https://www.ecfr.gov/current/title-8/section-1003.1","by":{"1":"34, 41, 49"}},{"t":"reg","label":"8 C.F.R. § 1003.3","url":"https://www.ecfr.gov/current/title-8/section-1003.3","by":{"1":"46"}},{"t":"case","label":"Beard v. Banks","cite":"542 U.S. 406","y":2004,"id":"2003/02-1603","sc":1,"sum":"In a 5-to-4 decision written by Justice Clarence Thomas, the Court found that the rule announced in Mills - that sentencing schemes could not prevent jurors from considering mitigating evidence that had not been accepted unanimously when deciding whether to apply the death penalty - was a new rule, because it was not compelled by previous Court decisions.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"Briones-Sanchez v. Heinauer","cite":"319 F.3d 324","y":2003,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/319/324/","by":{"2":"16"}},{"t":"case","label":"Carlos-Blaza v. Holder","cite":"611 F.3d 583","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/611/583/","by":{"2":"20"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"2":"8, 15"}},{"t":"case","label":"De Leon v. INS","cite":"115 F.3d 643","y":1997,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/115/643/","by":{"2":"7"}},{"t":"case","label":"(I) Cases—Continued: Dodd v. United States","cite":"545 U.S. 353","y":2005,"url":"https://supreme.justia.com/cases/federal/us/545/353/","sc":1,"by":{"2":"14, 22"}},{"t":"case","label":"Gideon v. Wainwright","cite":"372 U.S. 335","y":1963,"id":"1962/155","sc":1,"sum":"The Court held that the Sixth and Fourteenth Amendments guarantee a right of legal counsel to anyone accused of a crime.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"Granite Rock Co. v. International Bhd. of Teamsters","cite":"561 U.S. 287","y":2010,"id":"2009/08-1214","sc":1,"sum":"The Court held that federal courts have jurisdiction to determine whether or not a collective bargaining agreement was formed between two parties when the agreement is disputed, but neither party makes a challenge to the arbitration clause contained in the agreement.","sumSrc":"Oyez","by":{"2":"8"}},{"t":"case","label":"Herrera v. Collins","cite":"506 U.S. 390","y":1993,"id":"1992/91-7328","sc":1,"sum":"The Court held that the rejection of Herrera’s petition did not constitute cruel and unusual punishment under the Eighth Amendment. Chief Justice Rehnquist concluded that evidence of Herrera’s actual innocence was not relevant to his petition for a writ of habeas corpus absent some constitutional violation by the state of Texas.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"Kasten v. Saint-Gobain Performance Plastics Corp.","cite":"563 U.S. 1","y":2011,"id":"2010/09-834","sc":1,"sum":"The Court held that the Fair Labor Standards Act applies to a complaint, whether oral or written.","sumSrc":"Oyez","by":{"2":"8"}},{"t":"case","label":"Madrigal v. Holder","cite":"572 F.3d 239","y":2009,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/572/239/","by":{"2":"7"}},{"t":"case","label":"Nielsen v. Preap","cite":"139 S. Ct. 954","y":2019,"id":"2018/16-1363","sc":1,"sum":"The Ninth Circuit’s judgments—that respondents, who are deportable for certain specified crimes, are not subject to 8 U. S. C. §1226(c)(2)’s mandatory-detention requirement because they were not arrested by immigration officials as soon as they were released from jail—are reversed, and the cases are remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"15"}},{"t":"case","label":"Ocasio v. United States","cite":"136 S. Ct. 1423","y":2016,"id":"2015/14-361","sc":1,"sum":"The Court determined that a conspiracy to commit extortion can involve the purported victims of the extortion as members of the conspiracy.","sumSrc":"Oyez","by":{"2":"13"}},{"t":"case","label":"Patel v. Attorney Gen.","cite":"394 Fed. Appx. 941","y":2010,"court":"3d Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./394/941/","by":{"2":"7"}},{"t":"case","label":"Shular v. United States","cite":"140 S. Ct. 779","y":2020,"id":"2019/18-6662","sc":1,"sum":"The Court held that the Armed Career Criminal Act’s “serious drug offense” definition requires only that a state offense involve the conduct specified in the statute; it does not require that the state offense match certain generic offenses.","sumSrc":"Oyez","by":{"2":"13"}},{"t":"case","label":"United States v. Baker","cite":"197 F.3d 211","y":1999,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/197/211/","by":{"2":"17"}},{"t":"case","label":"United States v. Bastide-Hernandez","cite":"986 F.3d 1245","y":2021,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/986/1245/","by":{"2":"10"}},{"t":"case","label":"United States v. First","cite":"731 F.3d 998","y":2013,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/731/998/","op":1,"ar":2,"by":{"2":"17"}},{"t":"case","label":"United States v. Gonzalez-Ferretiz","cite":"813 Fed. Appx. 837","y":2020,"court":"4th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./813/837/","sum":"Rejecting attempt to avoid Section 1326(d) through claim that aggravated-felony determination was “ultra vires”.","sumSrc":"brief:2","by":{"2":"11"}},{"t":"case","label":"United States v. Parrales-Guzman","cite":"922 F.3d 706","y":2019,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/922/706/","op":1,"sum":"Rejecting argument that Section 1326(d)’s “bar on collateral attacks does not attach” where a defendant’s removal order was allegedly “void ab initio” because “it rested on an unconstitutionally vague statute”.","sumSrc":"brief:2","by":{"2":"11"}},{"t":"case","label":"United States v. Valenzuela-Bernal","cite":"458 U.S. 858","y":1982,"id":"1981/81-450","sc":1,"sum":"Respondent failed to establish a violation of the Fifth or Sixth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"19"}},{"t":"case","label":"United States v. Vonn","cite":"535 U.S. 55","y":2002,"id":"2001/00-973","sc":1,"sum":"The Court held 8-1 that silent defendant has the burden to satisfy the plain-error rule and unanimously that a reviewing court may consult the whole record when considering the effect of any error on substantial rights.","sumSrc":"Oyez","by":{"2":"8"}},{"t":"case","label":"Upper Skagit Indian Tribe v. Lundgren","cite":"138 S. Ct. 1649","y":2018,"id":"2017/17-387","sc":1,"sum":"The Court held that its prior decision in County of Yakima v. Confederated Tribes and Bands of Yakima Nation addressed only a question of statutory interpretation, not the question whether Indian tribes have sovereign immunity in rem lawsuits.","sumSrc":"Oyez","by":{"2":"8"}},{"t":"case","label":"West Virginia Univ. Hosps., Inc. v. Casey","cite":"499 U.S. 83","y":1991,"id":"1990/89-994","sc":1,"sum":"Fees for services rendered by experts in civil rights litigation may not be shifted to the losing party as part of \"a reasonable attorney's fee\" under § 1988.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"14"}},{"t":"case","label":"Zazueta-Carrillo v. Ashcroft","cite":"322 F.3d 1166","y":2003,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/322/1166/","by":{"2":"7"}},{"t":"const","label":"Amendment V","clauses":[["due-process-5","Due Process Clause (Fifth Amendment)"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"2":"16"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","by":{"2":"20"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)(9)"],"by":{"2":"16"}},{"t":"usc","label":"8 U.S.C. § 1202","url":"https://www.law.cornell.edu/uscode/text/8/1202","subs":["(a)(1)"],"by":{"2":"17"}},{"t":"usc","label":"8 U.S.C. § 1226","url":"https://www.law.cornell.edu/uscode/text/8/1226","subs":["(a)(2)"],"by":{"2":"16"}},{"t":"usc","label":"28 U.S.C. § 2244","url":"https://www.law.cornell.edu/uscode/text/28/2244","subs":["(d)(1)"],"by":{"2":"22"}}]};